    <title>Notification Preferences</title>
    <style>
      :root {
        color-scheme: light;
        --bg: #f3f6fb;
        --surface: #ffffff;
        --surface-alt: #f8faff;
        --text: #172033;
        --muted: #566179;
        --border: #c8d4e8;
        --accent: #3b82f6;
        --accent-strong: #1d4ed8;
        --shadow: 0 24px 60px rgba(23, 32, 51, 0.14);
      }

      * {
        box-sizing: border-box;
      }

      body {
        margin: 0;
        min-height: 100vh;
        font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        background:
          radial-gradient(circle at top, #ffffff 0%, #f3f6fb 45%, #e9eef8 100%);
        color: var(--text);
      }

      .skip-link {
        position: absolute;
        left: 1rem;
        top: -3rem;
        z-index: 10;
        padding: 0.75rem 1rem;
        border-radius: 0.75rem;
        background: var(--text);
        color: #ffffff;
        text-decoration: none;
      }

      .skip-link:focus {
        top: 1rem;
      }

      main {
        display: grid;
        place-items: center;
        min-height: 100vh;
        padding: 2rem 1rem;
      }

      .card {
        width: min(100%, 38rem);
        padding: clamp(1.5rem, 4vw, 2.5rem);
        border: 1px solid rgba(200, 212, 232, 0.9);
        border-radius: 1.5rem;
        background: rgba(255, 255, 255, 0.96);
        box-shadow: var(--shadow);
      }

      .eyebrow {
        margin: 0 0 0.75rem;
        color: var(--accent-strong);
        font-size: 0.875rem;
        font-weight: 700;
        letter-spacing: 0.08em;
        text-transform: uppercase;
      }

      h1 {
        margin: 0;
        font-size: clamp(1.9rem, 4vw, 2.6rem);
        line-height: 1.1;
      }

      .intro {
        margin: 1rem 0 0;
        max-width: 34rem;
        color: var(--muted);
        font-size: 1rem;
        line-height: 1.6;
      }

      form {
        margin-top: 2rem;
      }

      .form-field {
        margin: 0 0 1.5rem;
      }

      fieldset {
        margin: 0;
        padding: 1.25rem;
        border: 1px solid var(--border);
        border-radius: 1rem;
        background: var(--surface-alt);
      }

      legend {
        padding: 0 0.35rem;
        font-size: 1.05rem;
        font-weight: 700;
      }

      .option-list {
        display: grid;
        gap: 0.85rem;
        margin-top: 0.75rem;
      }

      .option {
        display: flex;
        align-items: center;
        gap: 0.875rem;
        padding: 1rem;
        border: 1px solid var(--border);
        border-radius: 0.95rem;
        background: var(--surface);
        cursor: pointer;
        transition:
          border-color 0.2s ease,
          box-shadow 0.2s ease,
          transform 0.2s ease;
      }

      .option:hover {
        border-color: #9bbcff;
        transform: translateY(-1px);
      }

      .option:focus-within {
        border-color: var(--accent-strong);
        box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.2);
      }

      .option input[type="radio"] {
        margin: 0;
        inline-size: 1.2rem;
        block-size: 1.2rem;
        accent-color: var(--accent-strong);
        flex: none;
      }

      .option-text {
        font-weight: 600;
      }

      .actions {
        display: flex;
        align-items: center;
        gap: 1rem;
        flex-wrap: wrap;
      }

      button {
        border: 0;
        border-radius: 999px;
        padding: 0.95rem 1.4rem;
        background: linear-gradient(135deg, var(--accent), var(--accent-strong));
        color: #ffffff;
        font: inherit;
        font-weight: 700;
        cursor: pointer;
        box-shadow: 0 14px 26px rgba(29, 78, 216, 0.25);
      }

      button:hover {
        filter: brightness(1.03);
      }

      button:focus-visible,
      .option input[type="radio"]:focus-visible {
        outline: 3px solid #111827;
        outline-offset: 3px;
      }

      .status {
        min-height: 1.5rem;
        margin: 0;
        color: var(--muted);
        font-weight: 600;
      }

      @media (max-width: 40rem) {
        .card {
          border-radius: 1.2rem;
        }

        fieldset {
          padding: 1rem;
        }
      }

      @media (forced-colors: active) {
        body {
          background: Canvas;
          color: CanvasText;
        }

        .card,
        fieldset,
        .option {
          border-color: ButtonBorder;
          background: Canvas;
          box-shadow: none;
        }

        .skip-link,
        button {
          border: 1px solid ButtonText;
          background: ButtonFace;
          color: ButtonText;
        }

        .status,
        .intro,
        .eyebrow {
          color: CanvasText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>
    <main id="main-content">
      <section class="card" aria-labelledby="page-title">
        <p class="eyebrow">Preferences</p>
        <h1 id="page-title">Choose your notification preference</h1>
        <p class="intro">
          Tell us how you prefer to receive notifications so we can deliver
          updates in the way that works best for you.
        </p>

        <form id="notification-form">
          <div class="form-field">
            <fieldset>
              <legend>How do you prefer to receive notifications?</legend>
              <div class="option-list">
                <label class="option" for="notification-email">
                  <input
                    id="notification-email"
                    type="radio"
                    name="notificationPreference"
                    value="Email"
                    required
                  />
                  <span class="option-text">Email</span>
                </label>

                <label class="option" for="notification-sms">
                  <input
                    id="notification-sms"
                    type="radio"
                    name="notificationPreference"
                    value="SMS"
                  />
                  <span class="option-text">SMS</span>
                </label>

                <label class="option" for="notification-push">
                  <input
                    id="notification-push"
                    type="radio"
                    name="notificationPreference"
                    value="Push Notifications"
                  />
                  <span class="option-text">Push Notifications</span>
                </label>
              </div>
            </fieldset>
          </div>

          <div class="actions">
            <button type="submit">Submit</button>
            <p id="form-status" class="status" aria-live="polite"></p>
          </div>
        </form>
      </section>
    </main>

    <script>
      const form = document.getElementById("notification-form");
      const status = document.getElementById("form-status");

      form.addEventListener("submit", function (event) {
        event.preventDefault();

        const selectedOption = form.querySelector(
          'input[name="notificationPreference"]:checked'
        );

        status.textContent = selectedOption
          ? "Preference saved: " + selectedOption.value
          : "Please choose a notification preference before submitting.";
      });
    </script>
  </body>
</html>
